/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read()
a=s.index('Local Lemma tini_label_ren ')
s=s[:a]+'''Local Lemma tini_label_single (a : var → label_term) (p l : label_term) :
  p.[l/].[a] = p.[l.[a] .: a].
Proof. rewrite tini_label_comp. apply tini_label_ext. intros [|]; reflexivity. Qed.

'''+s[a:]
s=s.replace('rewrite tini_label_comp in Hf.', 'rewrite tini_label_single in Hf.')
a=s.index('  destruct (tini_low_dec (tini_lat τ)) as [Hl|Hl];',s.index('Local Lemma tini_Balloc'))
b=s.index('  all: destruct (tini_Bun_of',a)
s=s[:a]+'''  destruct (tini_low_dec (tini_lat τ)) as [Hl|Hl].
  - pose (W' := {| tini_left := <[l1:=τ]> (tini_left W);
                  tini_right := <[l2:=τ]> (tini_right W);
                  tini_links := <[(l1,l2):=τ]> (tini_links W) |}).
  - pose (W' := {| tini_left := <[l1:=τ]> (tini_left W);
                  tini_right := <[l2:=τ]> (tini_right W); tini_links := tini_links W |}).
  all: assert (tini_bext W W') as HW by
    (split; [exact (tini_ext_insert _ _ _ HW1)|];
     split; [exact (tini_ext_insert _ _ _ HW2)|];
     simpl; intros k ν Hk; try assumption;
     rewrite (lookup_insert_ne (tini_links W) (l1,l2) k τ); [done|intros <-; congruence]).
'''+s[b:]
#  Avoid introducing bullets until the two world cases have been built.
s=s.replace('  - pose (W\\x27 := {| tini_left := <[l1:=τ]> (tini_left W);\\n                  tini_right := <[l2:=τ]> (tini_right W);\\n                  tini_links := <[(l1,l2):=τ]> (tini_links W) |}).\\n  - pose (W\\x27 := {| tini_left := <[l1:=τ]> (tini_left W);\\n                  tini_right := <[l2:=τ]> (tini_right W); tini_links := tini_links W |}).','''  1: pose (W' := {| tini_left := <[l1:=τ]> (tini_left W);
                  tini_right := <[l2:=τ]> (tini_right W);
                  tini_links := <[(l1,l2):=τ]> (tini_links W) |}).
  2: pose (W' := {| tini_left := <[l1:=τ]> (tini_left W);
                  tini_right := <[l2:=τ]> (tini_right W); tini_links := tini_links W |}).''')
open(p,'w').write(s)
PY"

